public static LineNum lastLineNum(GUPAgreementId _agreementId)
{
    return (select maxof(LineNum) from GUPPriceTermJournalTrans
        index hint TransIdx
        where GUPPriceTermJournalTrans.AgreementId == _agreementId).LineNum;
}

/// <summary>
/// Initiates the current table buffer by using the specified table buffer.
/// </summary>
/// <param name="_gupPriceTermJournalTable">
/// A <c>GUPPriceTermJournalTable</c> table buffer.
/// </param>
public void initfromGUPPriceTermJournalTable(GUPPriceTermJournalTable _gupPriceTermJournalTable)
{
    this.AgreementId = _gupPriceTermJournalTable.AgreementId;

    InventDim inventDimSite;
    inventDimSite.InventSiteId = _gupPriceTermJournalTable.InventSiteId;
    inventDimSite = InventDim::findOrCreate(inventDimSite);
    this.InventDimId = inventDimSite.InventDimId;

    this.TransDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    this.ValidFrom = _gupPriceTermJournalTable.ValidFrom;
    this.ValidTo = _gupPriceTermJournalTable.ValidTo;
}

/// <summary>
/// Initiates the current table buffer by using the specified table buffer.
/// </summary>
/// <param name="_gupPriceTermJournalTrans">
/// A <c>GUPPriceTermJournalTrans</c> table buffer.
/// </param>
public void initfromGUPPriceTermJournalTrans(GUPPriceTermJournalTrans _gupPriceTermJournalTrans)
{
    this.AgreementId                    = _gupPriceTermJournalTrans.AgreementId;
    this.CompoundCalculationBasis       = _gupPriceTermJournalTrans.CompoundCalculationBasis;
    this.Code                           = _gupPriceTermJournalTrans.Code;
    this.Value                          = _gupPriceTermJournalTrans.Value;
    this.LineNum                        = GUPPriceTermJournalTrans::lastLineNum(_gupPriceTermJournalTrans.AgreementId) + 1;
    this.InventDimId                    = _gupPriceTermJournalTrans.InventDimId;
    this.UnitId                         = _gupPriceTermJournalTrans.UnitId;
}

public static void lookupCode(FormStringControl _control,
                              PriceDiscAccountCode _accountCode = TableGroupAll::All,
                              PriceDiscAccountRelation _accountRelation = null)
{
    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange qbrAccountRelation;
    QueryBuildRange qbrAccountCode;
    SysTableLookup sysTableLookup;

    sysTableLookup = SysTableLookup::newParameters(tableNum(GUPPriceTermTable),_control,true);
    sysTableLookup.parmUseLookupValue(false);
    sysTableLookup.addLookupfield(fieldNum(GUPPriceTermTable, Code));
    sysTableLookup.addLookupfield(fieldNum(GUPPriceTermTable, Description));
    queryBuildDataSource = query.addDataSource(tableNum(GUPPriceTermTable));
    queryBuildDataSource.addSortField(fieldnum(GUPPriceTermTable,Code ));

    if (_accountRelation)
    {
        qbrAccountRelation = queryBuildDataSource.addRange(fieldNum(GUPPriceTermTable, AccountRelation));
        qbrAccountRelation.value(_accountRelation);
        qbrAccountCode = queryBuildDataSource.addRange(fieldNum(GUPPriceTermTable, AccountCode));
        qbrAccountCode.value(queryValue(_accountCode));
    }

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

public static GUPPriceTermJournalTrans find(GUPAgreementId     _agreementId,
                                            LineNum            _lineNum = 0,
                                            boolean            _update  = false)
{
    GUPPriceTermJournalTrans gupPriceTermJournalTrans;

    if (_agreementId)
    {
        if (_update)
        {
            gupPriceTermJournalTrans.selectForUpdate(_update);
        }
        if (_lineNum)
        {
            select firstonly gupPriceTermJournalTrans
                index hint TransIdx
                where gupPriceTermJournalTrans.AgreementId  == _agreementId
                &&    gupPriceTermJournalTrans.LineNum      == _lineNum;
        }
        else
        {
            select firstonly gupPriceTermJournalTrans
                index hint TransIdx
                where gupPriceTermJournalTrans.AgreementId == _agreementId;
        }
    }

    return gupPriceTermJournalTrans;
}

    public static boolean exist(GUPAgreementId     _agreementId,
                          LineNum           _lineNum = naReal())
    {
        if (!_agreementId)
        {
            return false;
        }

        if (_lineNum == naReal())
        {
            return (select firstonly RecId from gupPriceTermJournalTrans
                        index hint TransIdx
                        where gupPriceTermJournalTrans.AgreementId == _agreementId).RecId != 0;
        }

        return (select firstonly RecId from gupPriceTermJournalTrans
                    index hint TransIdx
                    where gupPriceTermJournalTrans.AgreementId == _agreementId
                    &&    gupPriceTermJournalTrans.LineNum     == _lineNum).RecId != 0;
	}

public void clearPricingRule()
{
    GUPPricingRule pricingRule = GUPPricingRule::find(this.PricingRule, true);
    if (pricingRule)
    {
        ttsbegin;
        pricingRule.delete();
        ttscommit;
    }
}

public boolean validate()
{
    boolean ret = this.checkJournalLineOverlap_Internal(this.LineNum)
        && this.checkJournalLineOverlap_External();

    return ret;
}

private boolean checkJournalLineOverlap_External()
{
    // check journal line with posted price term journal lines.
    GUPPriceTermJournalTable otherJournalTable;
    GUPPriceTermJournalTrans otherJournalTrans;
    GUPPricingRule otherPricingRule;

    GUPPricingRule currentRule = GUPPricingRule::find(this.PricingRule);
    GUPPriceTermJournalTable currentJournalTable = GUPPriceTermJournalTable::find(this.AgreementId);

    while select otherJournalTrans join otherJournalTable join otherPricingRule
        where otherJournalTrans.AgreementId == otherJournalTable.AgreementId
            && otherJournalTable.AgreementId != this.AgreementId
            && otherJournalTable.Status == GUPDisabledEnabled::Enabled
            && otherJournalTable.InventSiteId == currentJournalTable.InventSiteId
            && otherJournalTrans.Code == this.Code
            && otherJournalTrans.InventDimId == this.InventDimId
            && otherPricingRule.RecId == otherJournalTrans.PricingRule
            && otherPricingRule.PriceAttributeGroupName == currentRule.PriceAttributeGroupName
    {
        if (currentJournalTable.dateRangesOverlap(otherJournalTable)
            && currentRule.rangeOverlap(GUPPricingRule::find(otherJournalTrans.PricingRule)))
        {
            return checkFailed(strFmt(
                "@GlobalUnifiedPricing:GUPJournalCheckPost_PriceTerm_RangeOverlapExternal",
                this.LineNum,
                otherJournalTrans.AgreementId,
                otherJournalTrans.LineNum));
        }
    }

    return true;
}

private boolean checkJournalLineOverlap_Internal(LineNum _startIdx = this.LineNum)
{
    // check journal line with lines in the same journal.
    GUPPriceTermJournalTrans otherJournalTrans;
    GUPPricingRule otherPricingRule;

    GUPPricingRule currentRule = GUPPricingRule::find(this.PricingRule);

    while select otherJournalTrans join otherPricingRule
        where otherJournalTrans.AgreementId == this.AgreementId
            && otherJournalTrans.PricingRule == otherPricingRule.RecId
            && otherPricingRule.PriceAttributeGroupName == currentRule.PriceAttributeGroupName
            && otherJournalTrans.Code == this.Code
            && otherJournalTrans.InventDimId == this.InventDimId
            && otherJournalTrans.LineNum > _startIdx
    {
        if (currentRule.rangeOverlap(GUPPricingRule::find(otherJournalTrans.PricingRule)))
        {
            return checkFailed(strFmt(
                "@GlobalUnifiedPricing:GUPJournalCheckPost_PriceTerm_RangeOverlapInternal",
                this.LineNum,
                otherJournalTrans.LineNum));
        }
    }

    return true;
}

public void delete()
{
    ttsbegin;
    GUPPricingRule::find(this.PricingRule, true).delete();

    super();
    ttscommit;
}
